import ToursListing from "@/components/listing/tours-listing";
import Breadcrumb from "../header/breadcrumb";
import ReadMoreText from "./read-more-text";
import RelatedLinks from "./related-links";
import ItemListSchema from "./item-list-schema";
import FaqSchema from "./faq-schema";
import FaqAccordion from "./faq-accordion";

export default function Page({
  params,
  tourData,
  guides,
}: {
  params: any;
  tourData: any;
  guides?: any[];
}) {
  const initialFilterData = {
    service_types: [],
    accommodations: [],
    guiding: [],
    languages: [],
    duration: [],
    promotion_type: "",
    destination: params.destination ?? "",
    category: params.category ?? "",
    company: params.company ?? "",
    departureDate: "",
    start_location: "",
    end_location: "",
    lodging: [],
    activities: [],
    start: "",
    end: "",
    order: "sales",
    order_dir: "desc",
  };

  return (
    <main>
      <ItemListSchema
        pageUrl={params.pageUrl}
        pageTitle={params.title}
        tours={tourData?.tours ?? []}
      />
      <FaqSchema faq={params.faq} />
      <div className="tw-mx-auto tw-w-full tw-max-w-[1320px] tw-px-3 tw-mt-6 tw-mb-3">
        <Breadcrumb
          items={[
            ...params.parentCategories,
            {
              pageTitle: params.breadcrumbTitle,
              pageUrl: `/${params.pageUrl}`,
            },
          ]}
        />
        <h1 className="tw-font-display tw-text-2xl tw-font-bold tw-text-[#14101c] tw-mt-0 tw-mb-2">
          {params.title}
        </h1>
        {params.shortDescription && (
          <div
            className="tw-mt-2 tw-text-[15px] tw-leading-relaxed tw-text-[#5d556c] tw-font-display [&_p]:tw-m-0"
            style={{
              overflow: "hidden",
              display: "-webkit-box",
              WebkitLineClamp: 2,
              WebkitBoxOrient: "vertical",
            }}
            dangerouslySetInnerHTML={{
              __html: params.shortDescription,
            }}
          ></div>
        )}
      </div>

      <ToursListing
        params={params}
        initialFilterData={initialFilterData}
        initialTours={tourData.tours ?? []}
        initialTotal={tourData.total ?? 0}
        initialFilters={tourData.filters ?? {}}
        enableHashFilters
        footer={
          <>
            <div className="tw-mt-16">
              <RelatedLinks
                title={params.title}
                parentTitle={
                  params.parentCategories?.[params.parentCategories.length - 1]
                    ?.pageTitle ?? null
                }
                currentUrl={`/${params.pageUrl}`}
                childCategories={params.childCategories}
                childPages={params.childPages}
                pages={params.pages}
                pagesParentTitle={params.pagesParentTitle}
                categories={params.categories}
                guides={guides ?? []}
              />
            </div>
            {params.longDescription && (
              <div className="tw-mt-12">
                <h2 className="tw-mb-4 tw-font-display tw-text-lg tw-font-bold tw-tracking-tight tw-text-[#14101c]">
                  About {params.title}
                </h2>
                <ReadMoreText html={params.longDescription} />
              </div>
            )}
            <FaqAccordion faq={params.faq} />
          </>
        }
      />
    </main>
  );
}
