type TourItem = {
  id: number;
  name: string;
  slug: string;
  image: string;
  media?: { thumb?: string; collection_name: string }[];
};

type ItemListSchemaProps = {
  pageUrl: string;
  pageTitle: string;
  tours: TourItem[];
};

export default function ItemListSchema({
  pageUrl,
  pageTitle,
  tours,
}: ItemListSchemaProps) {
  const firstTen = tours.slice(0, 10);

  if (firstTen.length < 3) return null;

  const schema = {
    "@context": "https://schema.org",
    "@type": "ItemList",
    "@id": `https://travelshopbooking.com/${pageUrl}#itemlist`,
    name: pageTitle,
    itemListOrder: "https://schema.org/ItemListOrderAscending",
    itemListElement: firstTen.map((tour, index) => {
      const tourUrl = `https://travelshopbooking.com/tour/${tour.slug}`;

      // Ana görseli belirle: media koleksiyonundaki "main", yoksa image alanı
      const mainMedia = tour.media?.find((m) => m.collection_name === "main");
      const imageUrl = mainMedia?.thumb ?? tour.image ?? null;

      return {
        "@type": "ListItem",
        position: index + 1,
        item: {
          "@type": "TouristTrip",
          "@id": `${tourUrl}#tour`,
          name: tour.name,
          url: tourUrl,
          ...(imageUrl && { image: [imageUrl] }),
          offers: {
            "@type": "Offer",
            url: tourUrl,
            availability: "https://schema.org/InStock",
          },
        },
      };
    }),
  };

  return (
    <script
      type="application/ld+json"
      dangerouslySetInnerHTML={{ __html: JSON.stringify(schema) }}
    />
  );
}
